  "facts": [
    {"id": "F-01", "summary": "灯りを消してはいけない", "terms": ["灯り"], "setup": "ch01"}
  ],
  "locations": [
    {"id": "灯台", "travel_days": {"王都": 3}},
    {"id": "王都", "travel_days": {"灯台": 3}}
